<?php require_once 'includes/db.php'; $pageTitle='Fretes'; require 'includes/header.php'; $rows=$pdo->query("SELECT f.*,o.identificacao origem,d.identificacao destino,t.nome transportador,(SELECT COUNT(*) FROM frete_produtos fp WHERE fp.frete_id=f.id) itens FROM fretes f JOIN enderecos o ON o.id=f.origem_id JOIN enderecos d ON d.id=f.destino_id JOIN transportadores t ON t.id=f.transportador_id ORDER BY f.data_frete DESC,f.id DESC")->fetchAll(); ?><div class="page-heading"><div><h1 class="h3 mb-1">Fretes</h1><p class="text-secondary mb-0">Consulte os fretes e os produtos relacionados.</p></div><a href="frete_form.php" class="btn btn-primary">+ Gerar frete</a></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Código</th><th>Data</th><th>Trajeto</th><th>Transportador</th><th>Produtos</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="fw-semibold"><?=e($r['codigo'])?></td><td><?=date('d/m/Y',strtotime($r['data_frete']))?></td><td><?=e($r['origem'].' → '.$r['destino'])?></td><td><?=e($r['transportador'])?></td><td><?=$r['itens']?></td><td><?=e($r['status'])?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="text-center text-secondary">Nenhum frete cadastrado.</td></tr><?php endif; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
